import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

type Entry = [howTo: string, formula: string, example: string, question: string, answer: string];
type Copy = { gst: Entry; tax: Entry; salary: Entry };

const copy: Record<SupportedLocale, Copy> = {
  ko: {
    gst: ["세전 금액 또는 세후 합계, 계산 방향과 상품·서비스에 맞는 GST율을 입력하세요. HSN/SAC 분류와 주간 거래 여부는 직접 확인해야 합니다.", "세전 GST=세전 금액×입력률/100; 세후 합계=세전 금액+GST. 세후 입력이면 세전=합계/(1+입력률/100).", "세전 ₹10,000에 입력률 18%면 GST ₹1,800, 합계 ₹11,800입니다. 18%는 예시 입력값이며 모든 품목에 적용되는 단일 세율이 아닙니다.", "인도의 모든 상품에 18% GST가 적용되나요?", "아닙니다. GST율은 HSN/SAC 품목·서비스 분류와 공급 유형에 따라 달라집니다. 계산기는 품목을 판정하거나 CGST/SGST와 IGST를 분할하지 않습니다."],
    tax: ["AY 2026–27 신세제의 일반 과세소득을 입력하세요. 사업·급여·특별세율 소득, 거주자 자격과 다른 공제는 자동 판별하지 않습니다.", "누진세=₹4L까지 0% + ₹4–8L 5% + ₹8–12L 10% + ₹12–16L 15% + ₹16–20L 20% + ₹20–24L 25% + 초과 30%. 엔진은 단순 87A 환급/한계구제도 적용합니다.", "과세소득 ₹15L은 구간세액 ₹1,05,000, 평균세율 7%입니다. 이는 엔진 산출 예시이며 특별소득 세금, 부가세와 할증은 반영되지 않습니다.", "₹12L 이하이면 항상 세금이 0인가요?", "AY 2026–27 신세제의 87A 환급은 자격 있는 거주 개인에 한정되고 특별세율 소득에는 적용되지 않습니다. 계산기는 거주자·소득 구성 자격을 묻지 않아 최종 세액으로 볼 수 없습니다."],
    salary: ["연봉 또는 월급과 별도 입력 기여율을 입력하세요. 급여 모델은 엔진의 신세제 구간을 적용하지만 ₹75,000 표준공제, PF, 전문세, 세액공제, cess와 surcharge를 계산하지 않습니다.", "연봉 환산액=월급×12(월 입력 시). 모델 세액=신세제 누진 구간 및 단순 환급; 모델 순액=연봉−모델 세액−입력 기여율 금액.", "연봉 ₹15L, 별도 기여율 0%면 모델 소득세 ₹1,05,000, 추정 순액 ₹13.95L/년(월 ₹1,16,250)입니다. 표준공제나 급여별 공제 전 산식입니다.", "이 결과가 실제 인도 급여명세서인가요?", "아닙니다. FY 2025–26 신세제 급여소득에는 조건에 따라 ₹75,000 표준공제가 가능하지만 엔진은 이를 빼지 않습니다. EPF, 주별 전문세, TDS 정산, cess, surcharge와 개인 공제도 제외되어 정책 정확도 검증이 완료되지 않았습니다."],
  },
  en: {
    gst: ["Enter a pre-tax amount or total, select the direction, and supply the GST rate for the item or service. Verify its HSN/SAC classification and whether the supply is intra- or inter-state.", "GST on base=base×entered rate/100; total=base+GST. For an inclusive total, base=total/(1+entered rate/100).", "₹10,000 net at the entered 18% gives ₹1,800 GST and ₹11,800 total. 18% is this example's input, not one rate for every item.", "Does every Indian product have 18% GST?", "No. GST depends on HSN/SAC classification and supply details. This calculator does not classify the item or split CGST/SGST versus IGST."],
    tax: ["Enter ordinary taxable income for the AY 2026–27 new-regime scenario. The tool does not infer residence, income category, or eligibility for other deductions.", "Progressive tax=0% to ₹400,000 + 5% to ₹800,000 + 10% to ₹1,200,000 + 15% to ₹1,600,000 + 20% to ₹2,000,000 + 25% to ₹2,400,000 + 30% above. The engine also applies a simplified Section 87A rebate/marginal relief.", "At ₹1,500,000 taxable income, modeled slab tax is ₹105,000, a 7% average rate. This is the engine's example before special-rate income, cess and surcharge.", "Is tax always zero at income up to ₹1.2 million?", "The AY 2026–27 new-regime Section 87A rebate is limited to eligible resident individuals and does not offset tax on special-rate income. The calculator has no residence or income-type inputs, so this is not a final liability."],
    salary: ["Enter annual or monthly gross pay and any separate contribution assumption. The model applies its new-regime slabs but does not subtract the ₹75,000 standard salary deduction, PF, professional tax, credits, cess, or surcharge.", "Annualized gross=monthly pay×12 when monthly is selected. Modeled tax=slab calculation plus simplified rebate; modeled net=gross−modeled tax−entered contribution amount.", "At ₹1,500,000 annual gross and 0% separate contributions, modeled tax is ₹105,000 and estimated net is ₹1,395,000/year (₹116,250/month). This uses gross as the tax base before salary deductions.", "Is this my actual Indian take-home salary?", "No. For FY 2025–26, eligible new-regime salary income can receive a ₹75,000 standard deduction, which this engine omits. EPF, state professional tax, TDS reconciliation, cess, surcharge and individual deductions are also outside the model; policy accuracy remains unverified."],
  },
  ja: {
    gst: ["税抜額または税込合計、計算方向、商品・サービスに適用するGST率を入力します。HSN/SAC分類と州内・州間供給を別途確認してください。", "税抜GST=税抜額×入力率/100、合計=税抜額+GST。税込入力では税抜額=合計/(1+入力率/100)。", "税抜₹10,000に入力率18%ならGST ₹1,800、合計₹11,800です。18%は例の入力値で、全品目共通ではありません。", "インドの全商品に18% GSTがかかりますか？", "いいえ。GST率はHSN/SAC分類や供給条件で異なります。本ツールは品目を分類せず、CGST/SGSTとIGSTも分けません。"],
    tax: ["AY 2026–27新税制の一般課税所得を入力します。居住者資格、所得の種類、他の控除の適格性は自動判定しません。", "累進税=₹400,000まで0% + ₹800,000まで5% + ₹1,200,000まで10% + ₹1,600,000まで15% + ₹2,000,000まで20% + ₹2,400,000まで25% + 超過分30%。エンジンは87A還付・限界救済も簡略適用します。", "課税所得₹1,500,000ではモデル税額₹105,000、平均税率7%です。特殊税率所得、cess、surcharge前のエンジン例です。", "所得が₹1,200,000以下なら常に税額ゼロですか？", "AY 2026–27の新税制Section 87A還付は要件を満たす居住個人に限られ、特殊税率所得の税には使えません。居住地や所得区分を入力しないため、確定税額ではありません。"],
    salary: ["年収または月給と別途の拠出率を入力します。モデルは新税制の税率帯を使いますが、₹75,000給与所得控除、PF、職業税、税額控除、cess、surchargeを差し引きません。", "年額換算=月給×12。モデル税額=税率帯計算と簡略還付。モデル手取り=年収−モデル税額−入力拠出額。", "年収₹1,500,000、別拠出率0%ではモデル税額₹105,000、推定手取り₹1,395,000/年（₹116,250/月）です。総額を税基礎として控除前に計算します。", "これは実際のインドの手取りですか？", "いいえ。FY 2025–26の新税制では条件を満たす給与所得に₹75,000控除があり得ますが、エンジンは差し引きません。EPF、州職業税、TDS精算、cess、surcharge、個別控除も対象外で、政策精度は未検証です。"],
  },
  zh: {
    gst: ["输入未税金额或含税总额，选择方向并填写商品或服务的GST税率。请另行核实HSN/SAC分类以及州内或跨州供应。", "未税GST=未税金额×输入税率/100；总额=未税金额+GST。含税输入时，未税金额=总额/(1+输入税率/100)。", "未税₹10,000按输入18%计算，GST为₹1,800，总额₹11,800。18%只是本例输入，不适用于所有商品。", "印度所有商品都按18% GST吗？", "不是。税率取决于HSN/SAC分类和供应条件。本工具不分类商品，也不拆分CGST/SGST与IGST。"],
    tax: ["输入AY 2026–27新税制情景下的一般应税收入。工具不会判断居住身份、收入类别或其他扣除资格。", "累进税额=₹400,000内0% + 至₹800,000部分5% + 至₹1,200,000部分10% + 至₹1,600,000部分15% + 至₹2,000,000部分20% + 至₹2,400,000部分25% + 超出部分30%。引擎还简化处理87A抵免和边际减免。", "应税收入₹1,500,000时，模型分档税额为₹105,000，平均税率7%。这是不含特殊税率收入、cess和附加费的引擎示例。", "收入不超过₹1,200,000就一定免税吗？", "AY 2026–27新税制Section 87A抵免仅适用于符合条件的居民个人，且不能抵减特殊税率收入税额。工具没有居住身份或收入类型输入，因此不是最终税负。"],
    salary: ["输入年薪或月薪及单独假设的缴费率。模型使用新税制分档，但不扣除₹75,000标准工资扣除、PF、职业税、抵免、cess或附加费。", "年化工资=月薪×12。模型税额=分档税加简化抵免；模型净额=工资−模型税额−输入缴费。", "年薪₹1,500,000且另行缴费率0%时，模型税额₹105,000，估算净额₹1,395,000/年（₹116,250/月）。模型将总工资作为扣除前税基。", "这是我的实际印度到手工资吗？", "不是。FY 2025–26新税制下符合条件的工资可扣除₹75,000，但本引擎未扣除。EPF、邦职业税、TDS结算、cess、附加费和个人扣除也未计入，政策准确性仍待验证。"],
  },
  es: {
    gst: ["Introduce una base o total, elige el sentido e indica el tipo GST del bien o servicio. Verifica por separado la clasificación HSN/SAC y si el suministro es intra o interestatal.", "GST sobre base=base×tipo introducido/100; total=base+GST. Para importe con impuesto, base=total/(1+tipo introducido/100).", "Una base de ₹10.000 al 18% introducido genera ₹1.800 de GST y ₹11.800 en total. El 18% es el dato del ejemplo, no una tasa universal.", "¿Todos los productos indios llevan 18% de GST?", "No. El tipo depende de la clasificación HSN/SAC y del suministro. La herramienta no clasifica el producto ni separa CGST/SGST e IGST."],
    tax: ["Introduce ingresos imponibles ordinarios para el escenario del nuevo régimen AY 2026–27. No determina residencia, tipo de ingreso ni derecho a otras deducciones.", "Impuesto progresivo=0% hasta ₹400.000 + 5% hasta ₹800.000 + 10% hasta ₹1.200.000 + 15% hasta ₹1.600.000 + 20% hasta ₹2.000.000 + 25% hasta ₹2.400.000 + 30% del exceso. El motor aplica también una bonificación/compensación marginal simplificada de la sección 87A.", "Con ₹1.500.000 imponibles, el impuesto modelado por tramos es ₹105.000, un 7% medio. Es el ejemplo del motor antes de rentas a tipo especial, cess y recargo.", "¿Siempre es cero el impuesto hasta ₹1.200.000?", "La bonificación 87A del nuevo régimen AY 2026–27 se limita a personas residentes que cumplan los requisitos y no compensa impuestos sobre rentas a tipo especial. No se pregunta residencia ni tipo de ingreso; no es la liquidación final."],
    salary: ["Introduce el bruto anual o mensual y una hipótesis separada de contribución. El modelo usa los tramos del nuevo régimen, pero no resta la deducción salarial estándar de ₹75.000, PF, impuesto profesional, créditos, cess ni recargo.", "Bruto anualizado=mensual×12. Impuesto modelado=tramos más bonificación simplificada; neto modelado=bruto−impuesto−contribución introducida.", "Con ₹1.500.000 brutos anuales y 0% de contribución separada, el impuesto modelado es ₹105.000 y el neto estimado ₹1.395.000/año (₹116.250/mes). Usa el bruto como base antes de deducciones salariales.", "¿Es este mi salario neto real en India?", "No. En FY 2025–26 el nuevo régimen puede permitir ₹75.000 de deducción salarial, que el motor omite. También excluye EPF, impuesto profesional estatal, ajuste TDS, cess, recargo y deducciones personales; la precisión normativa sigue pendiente."],
  },
  "pt-br": {
    gst: ["Informe o valor líquido ou total, escolha o sentido e indique a taxa GST do produto ou serviço. Confirme separadamente a classificação HSN/SAC e se a operação é estadual ou interestadual.", "GST sobre a base=base×taxa informada/100; total=base+GST. Para valor com imposto, base=total/(1+taxa informada/100).", "Base de ₹10.000 a 18% informado gera ₹1.800 de GST e ₹11.800 no total. 18% é a taxa deste exemplo, não uma taxa universal.", "Todo produto indiano paga 18% de GST?", "Não. A taxa depende da classificação HSN/SAC e da operação. A ferramenta não classifica itens nem separa CGST/SGST de IGST."],
    tax: ["Informe a renda tributável ordinária para o cenário do novo regime AY 2026–27. O modelo não identifica residência, tipo de renda ou elegibilidade para outras deduções.", "Imposto progressivo=0% até ₹400.000 + 5% até ₹800.000 + 10% até ₹1.200.000 + 15% até ₹1.600.000 + 20% até ₹2.000.000 + 25% até ₹2.400.000 + 30% acima. O motor também aplica rebate/marginal relief simplificado da seção 87A.", "Com renda tributável de ₹1.500.000, o imposto modelado por faixas é ₹105.000, média de 7%. Exemplo do motor antes de renda especial, cess e adicional.", "A renda até ₹1.200.000 sempre fica sem imposto?", "O rebate 87A do novo regime AY 2026–27 vale apenas para residentes elegíveis e não compensa imposto sobre renda de alíquota especial. A ferramenta não pergunta residência ou composição da renda; não é cálculo final."],
    salary: ["Informe o salário bruto anual ou mensal e uma hipótese separada de contribuição. O modelo aplica as faixas do novo regime, mas não deduz o padrão salarial de ₹75.000, PF, imposto profissional, créditos, cess ou adicional.", "Bruto anualizado=mensal×12. Imposto modelado=faixas mais rebate simplificado; líquido modelado=bruto−imposto−contribuição informada.", "Com ₹1.500.000 brutos anuais e 0% de contribuição separada, o imposto modelado é ₹105.000 e o líquido estimado ₹1.395.000/ano (₹116.250/mês). O bruto é usado como base antes das deduções salariais.", "Este é meu salário líquido real na Índia?", "Não. No FY 2025–26 o novo regime pode permitir dedução salarial de ₹75.000, não aplicada pelo motor. EPF, imposto profissional estadual, ajuste de TDS, cess, adicional e deduções pessoais também ficam fora; a precisão legal ainda não foi concluída."],
  },
  de: {
    gst: ["Nettobetrag oder Gesamtsumme eingeben, Richtung wählen und den GST-Satz für Ware oder Leistung angeben. HSN/SAC-Einstufung und inner- oder zwischenstaatliche Lieferung separat prüfen.", "GST auf Basis=Basis×eingegebener Satz/100; gesamt=Basis+GST. Bei Bruttobetrag netto=gesamt/(1+eingegebener Satz/100).", "₹10.000 netto bei eingegebenen 18% ergeben ₹1.800 GST und ₹11.800 gesamt. 18% ist der Beispielwert, kein Einheitssatz.", "Gelten 18% GST für jedes Produkt in Indien?", "Nein. Der Satz hängt von HSN/SAC-Klassifizierung und Lieferart ab. Das Tool klassifiziert keine Ware und trennt CGST/SGST nicht von IGST."],
    tax: ["Steuerpflichtiges Normaleinkommen für das neue Regime AY 2026–27 eingeben. Wohnsitz, Einkunftsart und Anspruch auf weitere Abzüge werden nicht ermittelt.", "Progressive Steuer=0% bis ₹400.000 + 5% bis ₹800.000 + 10% bis ₹1.200.000 + 15% bis ₹1.600.000 + 20% bis ₹2.000.000 + 25% bis ₹2.400.000 + 30% darüber. Die Engine berücksichtigt vereinfacht Section-87A-Ermäßigung und Grenzentlastung.", "Bei ₹1.500.000 steuerpflichtigem Einkommen beträgt die Modellsteuer nach Stufen ₹105.000, durchschnittlich 7%. Das Beispiel gilt vor Sondersteuereinkommen, cess und Zuschlag.", "Ist die Steuer bis ₹1.200.000 immer null?", "Die Section-87A-Ermäßigung im neuen Regime AY 2026–27 gilt nur für berechtigte Ansässige und nicht für Sondersteuereinkommen. Wohnsitz und Einkunftsart werden nicht abgefragt; dies ist keine endgültige Steuerfestsetzung."],
    salary: ["Jahres- oder Monatsbrutto und einen separaten Beitragsansatz eingeben. Die Engine nutzt neue Tarifstufen, zieht aber weder den Gehaltsfreibetrag ₹75.000 noch PF, Berufssteuer, Gutschriften, cess oder Zuschlag ab.", "Annualisiertes Brutto=Monatslohn×12. Modellsteuer=Tarifstufen plus vereinfachte Ermäßigung; Modellnetto=Brutto−Steuer−eingegebener Beitrag.", "Bei ₹1.500.000 Jahresbrutto und 0% separatem Beitrag beträgt die Modellsteuer ₹105.000, das geschätzte Netto ₹1.395.000/Jahr (₹116.250/Monat). Brutto wird vor Gehaltsabzügen als Steuerbasis verwendet.", "Ist das mein tatsächliches indisches Nettogehalt?", "Nein. Im FY 2025–26 kann das neue Regime einen Gehaltsabzug von ₹75.000 erlauben, den die Engine auslässt. PF, staatliche Berufssteuer, TDS-Abgleich, cess, Zuschlag und persönliche Abzüge fehlen ebenfalls; die Rechtsgenauigkeit bleibt ungeprüft."],
  },
  fr: {
    gst: ["Saisissez une base HT ou un total, choisissez le sens et indiquez le taux GST du bien ou service. Vérifiez séparément sa classification HSN/SAC et la nature intra/interétatique de la fourniture.", "GST sur base=base×taux saisi/100; total=base+GST. Pour un montant TTC, base=total/(1+taux saisi/100).", "Une base de ₹10 000 avec 18% saisi génère ₹1 800 de GST et ₹11 800 au total. 18% est la valeur de l’exemple, pas un taux universel.", "Tous les produits indiens sont-ils à 18% de GST ?", "Non. Le taux dépend du classement HSN/SAC et de la fourniture. L’outil ne classe pas le produit et ne sépare pas CGST/SGST et IGST."],
    tax: ["Saisissez un revenu imposable ordinaire pour le scénario du nouveau régime AY 2026–27. Le modèle ne détermine ni résidence, ni catégorie de revenu, ni droit à d’autres déductions.", "Impôt progressif=0% jusqu’à ₹400 000 + 5% jusqu’à ₹800 000 + 10% jusqu’à ₹1 200 000 + 15% jusqu’à ₹1 600 000 + 20% jusqu’à ₹2 000 000 + 25% jusqu’à ₹2 400 000 + 30% au-delà. Le moteur applique aussi une réduction/relief marginal simplifié de la section 87A.", "À ₹1 500 000 imposables, l’impôt modélisé par tranches est ₹105 000, soit 7% en moyenne. Exemple avant revenus à taux spécial, cess et surtaxe.", "L’impôt est-il toujours nul jusqu’à ₹1 200 000 ?", "La réduction 87A du nouveau régime AY 2026–27 est réservée aux résidents éligibles et ne compense pas l’impôt sur les revenus à taux spécial. Le calculateur ne demande ni résidence ni catégorie de revenu; ce n’est pas le montant définitif."],
    salary: ["Saisissez le brut annuel ou mensuel et une hypothèse séparée de cotisation. Le modèle utilise les tranches du nouveau régime, mais ne déduit pas l’abattement salarial de ₹75 000, PF, taxe professionnelle, crédits, cess ni surtaxe.", "Brut annualisé=mensuel×12. Impôt modélisé=tranches et réduction simplifiée; net modélisé=brut−impôt−cotisation saisie.", "Avec ₹1 500 000 de brut annuel et 0% de cotisation séparée, l’impôt modélisé est ₹105 000 et le net estimé ₹1 395 000/an (₹116 250/mois). Le brut sert de base avant déductions salariales.", "Est-ce mon vrai salaire net en Inde ?", "Non. Pour FY 2025–26, le nouveau régime peut autoriser une déduction salariale de ₹75 000, absente du moteur. PF, taxe professionnelle de l’État, régularisation TDS, cess, surtaxe et déductions personnelles sont aussi exclues; la conformité juridique reste à vérifier."],
  },
  vi: {
    gst: ["Nhập giá trước thuế hoặc tổng, chọn chiều tính và mức GST của hàng hóa/dịch vụ. Hãy kiểm tra riêng mã HSN/SAC và giao dịch nội bang hay liên bang.", "GST trên giá cơ sở=giá cơ sở×tỷ lệ nhập/100; tổng=giá cơ sở+GST. Với tổng đã thuế, giá cơ sở=tổng/(1+tỷ lệ nhập/100).", "Giá trước thuế ₹10.000 với tỷ lệ nhập 18% cho GST ₹1.800, tổng ₹11.800. 18% chỉ là giá trị ví dụ, không phải mức chung cho mọi mặt hàng.", "Mọi hàng hóa ở Ấn Độ đều chịu GST 18%?", "Không. Mức thuế tùy phân loại HSN/SAC và loại cung ứng. Công cụ không phân loại hàng hoặc tách CGST/SGST với IGST."],
    tax: ["Nhập thu nhập chịu thuế thông thường cho tình huống chế độ mới AY 2026–27. Công cụ không xác định tình trạng cư trú, loại thu nhập hoặc quyền khấu trừ khác.", "Thuế lũy tiến=0% đến ₹400.000 + 5% đến ₹800.000 + 10% đến ₹1.200.000 + 15% đến ₹1.600.000 + 20% đến ₹2.000.000 + 25% đến ₹2.400.000 + 30% phần vượt. Engine áp dụng đơn giản khoản giảm và giảm nhẹ biên theo Section 87A.", "Thu nhập chịu thuế ₹1.500.000 cho thuế theo bậc ₹105.000, trung bình 7%. Đây là ví dụ của engine trước thu nhập thuế suất riêng, cess và phụ thu.", "Thu nhập đến ₹1.200.000 luôn không phải đóng thuế?", "Khoản giảm 87A của chế độ mới AY 2026–27 chỉ dành cho cá nhân cư trú đủ điều kiện và không bù thuế trên thu nhập áp thuế suất riêng. Công cụ không hỏi cư trú hay loại thu nhập nên không phải quyết toán cuối cùng."],
    salary: ["Nhập lương gộp năm hoặc tháng và giả định riêng về khoản đóng góp. Mô hình dùng bậc thuế chế độ mới nhưng không trừ khấu trừ lương ₹75.000, PF, thuế nghề nghiệp, tín dụng, cess hoặc phụ thu.", "Lương năm hóa=tháng×12. Thuế mô hình=bậc thuế và khoản giảm đơn giản; thực nhận mô hình=lương−thuế−khoản đóng đã nhập.", "Lương năm ₹1.500.000 và khoản đóng riêng 0% cho thuế mô hình ₹105.000, thực nhận ước tính ₹1.395.000/năm (₹116.250/tháng). Engine lấy lương gộp làm cơ sở trước khấu trừ.", "Đây có phải lương thực nhận ở Ấn Độ của tôi không?", "Không. FY 2025–26 có thể được khấu trừ lương ₹75.000 theo chế độ mới, nhưng engine không áp dụng. PF, thuế nghề nghiệp theo bang, đối chiếu TDS, cess, phụ thu và khấu trừ cá nhân cũng bị bỏ qua; độ chính xác pháp lý chưa được xác nhận."],
  },
  id: {
    gst: ["Masukkan nilai sebelum pajak atau total, pilih arah hitung, lalu isi tarif GST barang/jasa. Periksa sendiri klasifikasi HSN/SAC dan apakah pasokan intra- atau antarnegara bagian.", "GST atas dasar=dasar×tarif masukan/100; total=dasar+GST. Untuk total termasuk pajak, dasar=total/(1+tarif masukan/100).", "Nilai dasar ₹10.000 pada 18% masukan menghasilkan GST ₹1.800 dan total ₹11.800. Angka 18% hanya input contoh, bukan tarif semua barang.", "Apakah semua produk India dikenai GST 18%?", "Tidak. Tarif bergantung pada klasifikasi HSN/SAC dan jenis pasokan. Alat tidak mengklasifikasikan barang atau memisahkan CGST/SGST dari IGST."],
    tax: ["Masukkan penghasilan kena pajak biasa untuk skenario rezim baru AY 2026–27. Alat tidak menentukan residensi, kategori penghasilan, atau kelayakan potongan lain.", "Pajak progresif=0% sampai ₹400.000 + 5% sampai ₹800.000 + 10% sampai ₹1.200.000 + 15% sampai ₹1.600.000 + 20% sampai ₹2.000.000 + 25% sampai ₹2.400.000 + 30% sisanya. Mesin juga menerapkan rebate/marginal relief Section 87A secara sederhana.", "Pada penghasilan kena pajak ₹1.500.000, pajak model berdasarkan lapisan ₹105.000, rata-rata 7%. Contoh ini sebelum penghasilan bertarif khusus, cess dan surcharge.", "Apakah penghasilan hingga ₹1.200.000 selalu bebas pajak?", "Rebate 87A rezim baru AY 2026–27 hanya untuk individu residen yang memenuhi syarat dan tidak mengimbangi pajak penghasilan bertarif khusus. Alat tidak menanyakan residensi atau jenis penghasilan sehingga bukan kewajiban final."],
    salary: ["Masukkan gaji bruto tahunan atau bulanan dan asumsi kontribusi terpisah. Model memakai slab rezim baru, tetapi tidak mengurangi potongan gaji standar ₹75.000, PF, pajak profesi, kredit, cess atau surcharge.", "Bruto tahunan=bulanan×12. Pajak model=slab ditambah rebate sederhana; neto model=bruto−pajak−kontribusi yang dimasukkan.", "Gaji bruto ₹1.500.000 per tahun dan kontribusi terpisah 0% menghasilkan pajak model ₹105.000 dan neto estimasi ₹1.395.000/tahun (₹116.250/bulan). Bruto dipakai sebagai dasar sebelum potongan gaji.", "Apakah ini gaji bersih saya yang sebenarnya di India?", "Tidak. Untuk FY 2025–26, rezim baru dapat memberi potongan gaji ₹75.000 yang tidak diterapkan mesin. PF, pajak profesi negara bagian, rekonsiliasi TDS, cess, surcharge dan potongan pribadi juga tidak dihitung; akurasi aturan belum terverifikasi."],
  },
  th: {
    gst: ["กรอกยอดก่อนภาษีหรือยอดรวม เลือกทิศทางและอัตรา GST ของสินค้า/บริการ ตรวจสอบรหัส HSN/SAC และว่าเป็นการขายภายในรัฐหรือข้ามรัฐแยกต่างหาก", "GST บนฐานภาษี=ฐาน×อัตราที่กรอก/100; รวม=ฐาน+GST หากยอดรวมภาษีแล้ว ฐาน=ยอดรวม/(1+อัตราที่กรอก/100)", "ฐาน ₹10,000 ที่อัตรากรอก 18% ได้ GST ₹1,800 รวม ₹11,800 อัตรา 18% เป็นข้อมูลตัวอย่าง ไม่ใช่อัตราทุกสินค้า", "สินค้าอินเดียทุกชนิดเสีย GST 18% หรือไม่?", "ไม่ อัตราขึ้นกับรหัส HSN/SAC และลักษณะการขาย เครื่องมือไม่จำแนกสินค้าและไม่แยก CGST/SGST กับ IGST"],
    tax: ["กรอกรายได้ที่ต้องเสียภาษีทั่วไปสำหรับสถานการณ์ระบบใหม่ AY 2026–27 เครื่องมือไม่ระบุถิ่นที่อยู่ ประเภทรายได้ หรือสิทธิหักลดหย่อนอื่น", "ภาษีขั้นบันได=0% ถึง ₹400,000 + 5% ถึง ₹800,000 + 10% ถึง ₹1,200,000 + 15% ถึง ₹1,600,000 + 20% ถึง ₹2,000,000 + 25% ถึง ₹2,400,000 + 30% ส่วนเกิน เครื่องยังใช้ส่วนลด/บรรเทาภาษีส่วนเพิ่มตามมาตรา 87A แบบย่อ", "รายได้ ₹1,500,000 ให้ภาษีตามขั้นในโมเดล ₹105,000 เฉลี่ย 7% เป็นตัวอย่างก่อนรายได้อัตราพิเศษ cess และ surcharge", "รายได้ไม่เกิน ₹1,200,000 ไม่เสียภาษีเสมอไปหรือไม่?", "ส่วนลด 87A ระบบใหม่ AY 2026–27 จำกัดเฉพาะผู้มีถิ่นที่อยู่ที่เข้าเกณฑ์ และใช้ลดภาษีรายได้อัตราพิเศษไม่ได้ เครื่องมือไม่ถามถิ่นที่อยู่หรือประเภทรายได้ จึงไม่ใช่ยอดภาษีสุดท้าย"],
    salary: ["กรอกเงินเดือนรวมรายปีหรือรายเดือนและสมมติฐานเงินสมทบแยก โมเดลใช้ขั้นภาษีระบบใหม่ แต่ไม่หักค่าลดหย่อนเงินเดือนมาตรฐาน ₹75,000, PF, ภาษีวิชาชีพ, เครดิต, cess หรือ surcharge", "เงินเดือนรายปี=รายเดือน×12 ภาษีโมเดล=ภาษีขั้นบันไดและส่วนลดแบบย่อ; เงินสุทธิโมเดล=เงินเดือน−ภาษี−เงินสมทบที่กรอก", "เงินเดือน ₹1,500,000/ปีและเงินสมทบแยก 0% ให้ภาษีโมเดล ₹105,000 และเงินสุทธิประมาณ ₹1,395,000/ปี (₹116,250/เดือน) โดยใช้เงินเดือนรวมก่อนหักเป็นฐาน", "นี่คือเงินเดือนสุทธิจริงในอินเดียหรือไม่?", "ไม่ FY 2025–26 ระบบใหม่อาจให้หักเงินเดือน ₹75,000 แต่ engine ไม่หัก EPF, ภาษีวิชาชีพของรัฐ, การปรับ TDS, cess, surcharge และรายการส่วนบุคคลก็ไม่รวม ความแม่นยำตามกฎหมายยังไม่ได้ตรวจครบ"],
  },
  "zh-tw": {
    gst: ["輸入未稅金額或含稅總額，選擇方向並填入商品或服務的GST率。請另行確認HSN/SAC分類及州內或跨州供應。", "未稅GST=未稅金額×輸入率/100；總額=未稅金額+GST。含稅輸入時，未稅金額=總額/(1+輸入率/100)。", "未稅₹10,000以輸入18%計算，GST為₹1,800，總額₹11,800。18%只是此例輸入值，並非所有品項通用。", "印度所有商品都課18% GST嗎？", "不是。稅率取決於HSN/SAC分類與供應情況。本工具不分類品項，也不拆分CGST/SGST與IGST。"],
    tax: ["輸入AY 2026–27新制情境的一般應稅所得。工具不判斷居住身分、所得種類或其他扣除資格。", "累進稅額=₹400,000內0% + 至₹800,000部分5% + 至₹1,200,000部分10% + 至₹1,600,000部分15% + 至₹2,000,000部分20% + 至₹2,400,000部分25% + 超額部分30%。引擎另簡化套用87A減免與邊際減免。", "應稅所得₹1,500,000時，模型分級稅額₹105,000，平均7%。此為特殊稅率所得、cess與附加稅前的引擎例子。", "收入不超過₹1,200,000就一定免稅嗎？", "AY 2026–27新制87A減免僅適用符合資格的居民個人，不能抵減特殊稅率所得稅。工具不輸入居住身分或所得種類，因此不是最終稅額。"],
    salary: ["輸入年薪或月薪及另行假設的提繳率。模型採新制級距，但不扣₹75,000薪資標準扣除、PF、職業稅、抵免、cess或附加稅。", "年化薪資=月薪×12。模型稅額=級距計算及簡化減免；模型淨額=薪資−模型稅額−輸入提繳。", "年薪₹1,500,000且另行提繳率0%時，模型稅額₹105,000，估算淨額₹1,395,000/年（₹116,250/月）。模型以扣除前總薪資作為稅基。", "這是我在印度實際領到的淨薪嗎？", "不是。FY 2025–26新制可能提供₹75,000薪資扣除，但引擎未扣除；EPF、邦職業稅、TDS結算、cess、附加稅及個人扣除也不包含，法規準確性尚未完成驗證。"],
  },
  it: {
    gst: ["Inserisci base imponibile o totale, scegli la direzione e indica l’aliquota GST del bene/servizio. Verifica a parte la classificazione HSN/SAC e se la fornitura è intra- o interstatale.", "GST sulla base=base×aliquota inserita/100; totale=base+GST. Per importo con imposta, base=totale/(1+aliquota inserita/100).", "Una base di ₹10.000 al 18% inserito genera ₹1.800 GST e ₹11.800 totali. Il 18% è il dato dell’esempio, non un’aliquota universale.", "Tutti i prodotti indiani sono tassati al 18% GST?", "No. L’aliquota dipende dalla classificazione HSN/SAC e dalla fornitura. Lo strumento non classifica il bene né separa CGST/SGST da IGST."],
    tax: ["Inserisci il reddito imponibile ordinario per lo scenario del nuovo regime AY 2026–27. Il modello non determina residenza, categoria di reddito o diritto ad altre deduzioni.", "Imposta progressiva=0% fino a ₹400.000 + 5% fino a ₹800.000 + 10% fino a ₹1.200.000 + 15% fino a ₹1.600.000 + 20% fino a ₹2.000.000 + 25% fino a ₹2.400.000 + 30% oltre. Il motore applica in modo semplificato rebate e marginal relief della sezione 87A.", "Con ₹1.500.000 imponibili, l’imposta modellata per scaglioni è ₹105.000, media 7%. Esempio prima di redditi a aliquota speciale, cess e sovrattassa.", "Fino a ₹1.200.000 l’imposta è sempre zero?", "Il rebate 87A del nuovo regime AY 2026–27 è riservato ai residenti idonei e non compensa imposte su redditi a aliquota speciale. Non essendoci input su residenza o categoria, non è il debito definitivo."],
    salary: ["Inserisci il lordo annuo o mensile e un’ipotesi separata di contribuzione. Il modello applica le fasce del nuovo regime, ma non sottrae la deduzione salariale standard ₹75.000, PF, tassa professionale, crediti, cess o sovrattassa.", "Lordo annualizzato=mensile×12. Imposta modellata=scaglioni e rebate semplificato; netto modellato=lordo−imposta−contributo inserito.", "Con lordo annuo ₹1.500.000 e contributo separato 0%, l’imposta modellata è ₹105.000 e il netto stimato ₹1.395.000/anno (₹116.250/mese). Il lordo è usato come base prima delle deduzioni.", "È il mio vero stipendio netto in India?", "No. Nel FY 2025–26 il nuovo regime può consentire una deduzione salariale di ₹75.000, non applicata dal motore. Sono esclusi anche EPF, imposta professionale statale, conguaglio TDS, cess, sovrattassa e deduzioni personali; la precisione normativa resta da verificare."],
  },
  nl: {
    gst: ["Voer een bedrag exclusief of inclusief GST in, kies de richting en geef het toepasselijke GST-tarief op. Controleer de HSN/SAC-classificatie en of de levering binnen of tussen staten plaatsvindt.", "GST over basis=basis×ingevoerd tarief/100; totaal=basis+GST. Bij een totaal inclusief belasting is basis=totaal/(1+ingevoerd tarief/100).", "₹10.000 exclusief GST bij ingevoerde 18% geeft ₹1.800 GST en ₹11.800 totaal. 18% is de voorbeeldinvoer, niet één tarief voor alle goederen.", "Geldt 18% GST voor elk Indiaas product?", "Nee. Het tarief hangt af van HSN/SAC en de levering. De tool classificeert het product niet en splitst CGST/SGST en IGST niet uit."],
    tax: ["Voer gewoon belastbaar inkomen in voor het nieuwe-regimescenario AY 2026–27. De tool bepaalt geen woonplaats, inkomenscategorie of recht op andere aftrekposten.", "Progressieve belasting=0% tot ₹400.000 + 5% tot ₹800.000 + 10% tot ₹1.200.000 + 15% tot ₹1.600.000 + 20% tot ₹2.000.000 + 25% tot ₹2.400.000 + 30% daarboven. De engine past Section 87A-korting en marginal relief vereenvoudigd toe.", "Bij ₹1.500.000 belastbaar inkomen is de modelbelasting volgens schijven ₹105.000, gemiddeld 7%. Voorbeeld vóór speciaal belast inkomen, cess en toeslag.", "Is de belasting tot ₹1.200.000 altijd nul?", "De Section 87A-korting van het nieuwe regime AY 2026–27 geldt alleen voor in aanmerking komende inwoners en niet voor speciaal belast inkomen. Woonplaats en inkomenssoort worden niet gevraagd; dit is geen definitieve aanslag."],
    salary: ["Voer jaar- of maandbruto en een aparte bijdrage-aanname in. Het model gebruikt de nieuwe tariefschijven, maar trekt de salarisstandaardkorting ₹75.000, PF, beroepsbelasting, credits, cess of toeslag niet af.", "Geannualiseerd bruto=maandloon×12. Modelbelasting=schijven plus vereenvoudigde korting; modelnetto=bruto−belasting−ingevoerde bijdrage.", "Bij ₹1.500.000 jaarbruto en 0% aparte bijdrage is de modelbelasting ₹105.000 en geschat netto ₹1.395.000/jaar (₹116.250/maand). Het bruto geldt als belastingbasis vóór salaris-aftrek.", "Is dit mijn werkelijke nettoloon in India?", "Nee. In FY 2025–26 kan het nieuwe regime een salarisstandaardkorting van ₹75.000 toestaan; de engine past die niet toe. PF, deelstaat-beroepsbelasting, TDS-verrekening, cess, toeslag en persoonlijke aftrek ontbreken ook; juridische nauwkeurigheid is niet afgerond."],
  },
  hi: {
    gst: ["कर-पूर्व राशि या कुल दें, दिशा चुनें और वस्तु/सेवा की GST दर भरें। HSN/SAC वर्गीकरण और राज्य के भीतर या बाहर की आपूर्ति अलग से जाँचें।", "आधार पर GST=आधार×दर्ज दर/100; कुल=आधार+GST। कर सहित कुल में आधार=कुल/(1+दर्ज दर/100)।", "₹10,000 कर-पूर्व राशि पर दर्ज 18% से GST ₹1,800 और कुल ₹11,800 है। 18% उदाहरण का इनपुट है, सभी वस्तुओं की दर नहीं।", "क्या भारत के हर उत्पाद पर 18% GST है?", "नहीं। दर HSN/SAC वर्गीकरण और आपूर्ति पर निर्भर है। टूल वस्तु वर्गीकृत नहीं करता और CGST/SGST तथा IGST को अलग नहीं करता।"],
    tax: ["AY 2026–27 नई कर व्यवस्था के सामान्य करयोग्य आय परिदृश्य की आय दें। टूल निवास, आय श्रेणी या अन्य कटौती की पात्रता नहीं पहचानता।", "प्रगतिशील कर=₹400,000 तक 0% + ₹800,000 तक 5% + ₹1,200,000 तक 10% + ₹1,600,000 तक 15% + ₹2,000,000 तक 20% + ₹2,400,000 तक 25% + ऊपर 30%। इंजन Section 87A rebate और marginal relief भी सरल रूप में लागू करता है।", "₹1,500,000 करयोग्य आय पर मॉडल स्लैब कर ₹105,000, औसत 7% है। विशेष दर की आय, cess और surcharge से पहले का इंजन उदाहरण।", "क्या ₹1,200,000 तक आय पर हमेशा कर शून्य है?", "AY 2026–27 नई व्यवस्था की 87A छूट केवल पात्र निवासी व्यक्तियों के लिए है और विशेष-दर आय के कर को कम नहीं करती। टूल निवास या आय प्रकार नहीं पूछता, इसलिए यह अंतिम देयता नहीं है।"],
    salary: ["वार्षिक या मासिक सकल वेतन और अलग योगदान धारणा दें। मॉडल नई व्यवस्था की स्लैब दरें लगाता है, पर ₹75,000 मानक वेतन कटौती, PF, पेशेवर कर, क्रेडिट, cess या surcharge नहीं घटाता।", "वार्षिक सकल=मासिक×12। मॉडल कर=स्लैब और सरल rebate; मॉडल नेट=सकल−कर−दर्ज योगदान।", "₹1,500,000 वार्षिक सकल और अलग योगदान 0% पर मॉडल कर ₹105,000, अनुमानित नेट ₹1,395,000/वर्ष (₹116,250/माह) है। सकल को वेतन कटौतियों से पहले कर आधार माना गया है।", "क्या यह मेरा वास्तविक भारतीय टेक-होम वेतन है?", "नहीं। FY 2025–26 में नई व्यवस्था ₹75,000 वेतन कटौती दे सकती है, जिसे इंजन छोड़ता है। PF, राज्य पेशेवर कर, TDS मिलान, cess, surcharge और व्यक्तिगत कटौतियाँ भी शामिल नहीं; कानूनी सटीकता अभी सत्यापित नहीं है।"],
  },
  ru: {
    gst: ["Введите сумму до налога или итог, выберите направление и укажите GST для товара/услуги. Отдельно проверьте классификацию HSN/SAC и поставку внутри штата или между штатами.", "GST на базу=база×введенная ставка/100; итог=база+GST. Для суммы с налогом база=итог/(1+введенная ставка/100).", "База ₹10 000 при введенных 18% дает GST ₹1 800 и итог ₹11 800. 18% — ставка примера, а не единая ставка для всех товаров.", "Для каждого индийского товара действует GST 18%?", "Нет. Ставка зависит от классификации HSN/SAC и вида поставки. Инструмент не классифицирует товар и не разделяет CGST/SGST и IGST."],
    tax: ["Введите обычный налогооблагаемый доход для сценария нового режима AY 2026–27. Инструмент не определяет резидентство, категорию дохода или право на другие вычеты.", "Прогрессивный налог=0% до ₹400 000 + 5% до ₹800 000 + 10% до ₹1 200 000 + 15% до ₹1 600 000 + 20% до ₹2 000 000 + 25% до ₹2 400 000 + 30% сверх. Движок упрощенно применяет скидку/предельное облегчение по Section 87A.", "При налогооблагаемом доходе ₹1 500 000 модельный налог по диапазонам ₹105 000, средняя ставка 7%. Пример до специального дохода, cess и надбавки.", "Доход до ₹1 200 000 всегда не облагается?", "Скидка 87A нового режима AY 2026–27 доступна только подходящим резидентам и не уменьшает налог со специального дохода. Инструмент не спрашивает резидентство или вид дохода, поэтому итог не окончательный."],
    salary: ["Введите годовую или месячную зарплату брутто и отдельное предположение о взносах. Модель применяет новые диапазоны, но не вычитает стандартный зарплатный вычет ₹75 000, PF, профессиональный налог, кредиты, cess или надбавку.", "Годовой брутто=месячный×12. Модельный налог=диапазоны плюс упрощенная скидка; модельное нетто=брутто−налог−введенный взнос.", "При годовом брутто ₹1 500 000 и отдельных взносах 0% модельный налог ₹105 000, оценка нетто ₹1 395 000/год (₹116 250/мес.). Брутто используется как база до зарплатных вычетов.", "Это моя реальная зарплата на руки в Индии?", "Нет. В FY 2025–26 новый режим может предусматривать зарплатный вычет ₹75 000, который движок не применяет. Также не учтены PF, профессиональный налог штата, сверка TDS, cess, надбавка и личные вычеты; юридическая точность не подтверждена."],
  },
  tr: {
    gst: ["Vergi öncesi tutarı veya toplamı girin, yönü seçin ve mal/hizmet için GST oranını belirtin. HSN/SAC sınıflandırmasını ve eyalet içi ya da eyaletler arası tedariki ayrıca doğrulayın.", "Matrah üzerinden GST=matrah×girilen oran/100; toplam=matrah+GST. Vergi dahil toplamda matrah=toplam/(1+girilen oran/100).", "₹10.000 vergi öncesi tutar, girilen %18 ile ₹1.800 GST ve ₹11.800 toplam verir. %18 örnek girişidir, tüm ürünlere ait tek oran değildir.", "Hindistan'daki her ürüne %18 GST mi uygulanır?", "Hayır. Oran HSN/SAC sınıfına ve tedarik türüne bağlıdır. Araç ürünü sınıflandırmaz veya CGST/SGST ile IGST'yi ayırmaz."],
    tax: ["AY 2026–27 yeni rejim senaryosu için olağan vergilendirilebilir geliri girin. Araç ikameti, gelir türünü veya diğer indirim haklarını belirlemez.", "Artan oranlı vergi=₹400.000'e kadar %0 + ₹800.000'e kadar %5 + ₹1.200.000'e kadar %10 + ₹1.600.000'e kadar %15 + ₹2.000.000'e kadar %20 + ₹2.400.000'e kadar %25 + üzeri %30. Motor Section 87A indirimi/marjinal rahatlamayı basitleştirerek uygular.", "₹1.500.000 vergilendirilebilir gelirde model dilim vergisi ₹105.000, ortalama %7'dir. Özel oranlı gelir, cess ve ek vergi öncesi motor örneği.", "₹1.200.000'e kadar gelirde vergi her zaman sıfır mı?", "AY 2026–27 yeni rejimindeki 87A indirimi yalnızca uygun mukim bireylere aittir ve özel oranlı gelir vergisini mahsup etmez. Araç ikamet veya gelir türü sormadığından nihai vergi değildir."],
    salary: ["Yıllık veya aylık brüt ücreti ve ayrı katkı varsayımını girin. Model yeni rejim dilimlerini kullanır fakat ₹75.000 standart ücret indirimini, PF'yi, meslek vergisini, kredileri, cess'i veya ek vergiyi düşmez.", "Yıllık brüt=aylık×12. Model vergi=dilimler ve basit indirim; model neti=brüt−vergi−girilen katkı.", "₹1.500.000 yıllık brüt ve ayrı katkı %0 iken model vergi ₹105.000, net tahmini ₹1.395.000/yıl (₹116.250/ay) olur. Brüt, ücret indirimlerinden önce matrah sayılır.", "Bu Hindistan'daki gerçek net maaşım mı?", "Hayır. FY 2025–26 yeni rejiminde ₹75.000 maaş indirimi mümkün olabilir; motor bunu uygulamaz. PF, eyalet meslek vergisi, TDS mutabakatı, cess, ek vergi ve kişisel indirimler de dahil değildir; hukuki doğruluk tamamlanmamıştır."],
  },
  pl: {
    gst: ["Wpisz kwotę netto lub brutto, wybierz kierunek i podaj stawkę GST dla towaru/usługi. Osobno sprawdź klasyfikację HSN/SAC i dostawę w obrębie stanu lub między stanami.", "GST od podstawy=podstawa×wpisana stawka/100; suma=podstawa+GST. Przy kwocie z podatkiem podstawa=suma/(1+wpisana stawka/100).", "₹10 000 netto przy wpisanych 18% daje ₹1 800 GST i ₹11 800 razem. 18% to wartość przykładu, nie jedna stawka dla wszystkich produktów.", "Czy każdy produkt w Indiach ma 18% GST?", "Nie. Stawka zależy od klasyfikacji HSN/SAC i rodzaju dostawy. Narzędzie nie klasyfikuje towaru ani nie rozdziela CGST/SGST od IGST."],
    tax: ["Wpisz zwykły dochód podlegający opodatkowaniu dla nowego reżimu AY 2026–27. Narzędzie nie ustala rezydencji, rodzaju dochodu ani prawa do innych odliczeń.", "Podatek progresywny=0% do ₹400 000 + 5% do ₹800 000 + 10% do ₹1 200 000 + 15% do ₹1 600 000 + 20% do ₹2 000 000 + 25% do ₹2 400 000 + 30% powyżej. Silnik upraszcza ulgę i relief krańcowy Section 87A.", "Przy dochodzie ₹1 500 000 modelowy podatek według progów to ₹105 000, średnio 7%. Przykład przed dochodem o specjalnej stawce, cess i dopłatą.", "Czy dochód do ₹1 200 000 zawsze oznacza zerowy podatek?", "Ulga 87A nowego reżimu AY 2026–27 dotyczy tylko kwalifikujących się rezydentów i nie kompensuje podatku od dochodu o specjalnej stawce. Narzędzie nie pyta o rezydencję ani typ dochodu, więc wynik nie jest ostatecznym zobowiązaniem."],
    salary: ["Wpisz roczne lub miesięczne brutto i osobne założenie składek. Model stosuje progi nowego reżimu, ale nie odejmuje standardowego odliczenia płacowego ₹75 000, PF, podatku zawodowego, ulg, cess ani dopłaty.", "Roczne brutto=miesięczne×12. Podatek modelowy=progi i uproszczona ulga; netto modelowe=brutto−podatek−wpisana składka.", "Przy ₹1 500 000 rocznie i osobnych składkach 0% podatek modelowy wynosi ₹105 000, a szacowane netto ₹1 395 000/rok (₹116 250/mies.). Brutto jest podstawą przed odliczeniami płacowymi.", "Czy to moje rzeczywiste wynagrodzenie netto w Indiach?", "Nie. W FY 2025–26 nowy reżim może dopuszczać odliczenie płacowe ₹75 000, którego silnik nie stosuje. Nie uwzględnia też PF, podatku zawodowego stanu, rozliczenia TDS, cess, dopłaty ani ulg osobistych; zgodność prawna wymaga dalszej weryfikacji."],
  },
  fil: {
    gst: ["Ilagay ang halagang wala pang buwis o kabuuan, piliin ang direksiyon at ilagay ang GST rate ng produkto/serbisyo. Suriin nang hiwalay ang HSN/SAC at kung intra-state o inter-state ang supply.", "GST sa base=base×ipinasok na rate/100; kabuuan=base+GST. Kung kasama na ang buwis, base=kabuuan/(1+ipinasok na rate/100).", "Ang ₹10,000 net sa ipinasok na 18% ay may ₹1,800 GST at ₹11,800 kabuuan. Halimbawa lang ang 18%, hindi iisang rate para sa lahat.", "18% GST ba ang lahat ng produkto sa India?", "Hindi. Nakadepende ang rate sa HSN/SAC at uri ng supply. Hindi kinikilala ng tool ang produkto o hinihiwalay ang CGST/SGST at IGST."],
    tax: ["Ilagay ang ordinary taxable income para sa bagong-regime scenario ng AY 2026–27. Hindi tinutukoy ng tool ang residency, uri ng kita o eligibility sa ibang deduction.", "Progressive tax=0% hanggang ₹400,000 + 5% hanggang ₹800,000 + 10% hanggang ₹1,200,000 + 15% hanggang ₹1,600,000 + 20% hanggang ₹2,000,000 + 25% hanggang ₹2,400,000 + 30% sa lampas. Pinapasimple rin ng engine ang Section 87A rebate/marginal relief.", "Sa ₹1,500,000 taxable income, ₹105,000 ang modelong slab tax, average 7%. Halimbawa bago special-rate income, cess at surcharge.", "Laging walang buwis hanggang ₹1,200,000 ang kita?", "Ang 87A rebate sa bagong regime AY 2026–27 ay para lang sa kuwalipikadong resident individuals at hindi ibinabawas sa buwis sa special-rate income. Hindi itinatanong ng tool ang residency o income type kaya hindi ito final tax liability."],
    salary: ["Ilagay ang taunang o buwanang gross pay at hiwalay na palagay sa kontribusyon. Gamit ng modelo ang bagong-regime slabs ngunit hindi ibinabawas ang ₹75,000 standard salary deduction, PF, professional tax, credits, cess o surcharge.", "Annualized gross=monthly×12. Modelong buwis=slabs at pinasimpleng rebate; modelong net=gross−buwis−ipinasok na kontribusyon.", "Sa ₹1,500,000 annual gross at 0% hiwalay na kontribusyon, ₹105,000 ang modelong buwis at ₹1,395,000/taon (₹116,250/buwan) ang net estimate. Gross ang base bago salary deductions.", "Ito ba ang aktuwal kong take-home pay sa India?", "Hindi. Sa FY 2025–26, maaaring may ₹75,000 salary deduction sa bagong regime pero hindi ito ibinabawas ng engine. Wala rin ang PF, state professional tax, TDS reconciliation, cess, surcharge at personal deductions; hindi pa kumpleto ang legal accuracy."],
  },
  bn: {
    gst: ["কর-পূর্ব অঙ্ক বা মোট দিন, দিক বাছুন এবং পণ্য/সেবার GST হার লিখুন। HSN/SAC শ্রেণি ও একই রাজ্যের বা আন্তঃরাজ্য সরবরাহ আলাদা যাচাই করুন।", "ভিত্তির ওপর GST=ভিত্তি×প্রদত্ত হার/100; মোট=ভিত্তি+GST। করসহ মোটে ভিত্তি=মোট/(1+প্রদত্ত হার/100)।", "₹10,000 কর-পূর্ব অঙ্কে প্রদত্ত 18% হলে GST ₹1,800, মোট ₹11,800। 18% শুধু উদাহরণের হার, সব পণ্যের একক হার নয়।", "ভারতের প্রতিটি পণ্যে কি 18% GST?", "না। হার HSN/SAC শ্রেণি ও সরবরাহের ধরন অনুযায়ী বদলায়। টুল পণ্য শ্রেণিবদ্ধ করে না বা CGST/SGST ও IGST ভাগ করে না।"],
    tax: ["AY 2026–27 নতুন ব্যবস্থার সাধারণ করযোগ্য আয় দিন। টুল আবাসিক অবস্থা, আয়ের ধরন বা অন্য ছাড়ের যোগ্যতা নির্ধারণ করে না।", "প্রগতিশীল কর=₹400,000 পর্যন্ত 0% + ₹800,000 পর্যন্ত 5% + ₹1,200,000 পর্যন্ত 10% + ₹1,600,000 পর্যন্ত 15% + ₹2,000,000 পর্যন্ত 20% + ₹2,400,000 পর্যন্ত 25% + অতিরিক্তে 30%। ইঞ্জিন Section 87A ছাড়/প্রান্তিক স্বস্তি সরলীকৃতভাবে প্রয়োগ করে।", "₹1,500,000 করযোগ্য আয়ে মডেল স্ল্যাব কর ₹105,000, গড় 7%। বিশেষ-হার আয়, cess ও surcharge-এর আগের ইঞ্জিন উদাহরণ।", "₹1,200,000 পর্যন্ত আয়ে কি কর সবসময় শূন্য?", "AY 2026–27 নতুন ব্যবস্থার 87A ছাড় কেবল যোগ্য আবাসিক ব্যক্তির জন্য এবং বিশেষ-হার আয়ের কর কমায় না। টুল আবাস বা আয়ের ধরন জিজ্ঞেস করে না; এটি চূড়ান্ত কর নয়।"],
    salary: ["বার্ষিক বা মাসিক মোট বেতন ও আলাদা অবদানের অনুমান দিন। মডেল নতুন ব্যবস্থার স্ল্যাব ব্যবহার করে, কিন্তু ₹75,000 বেতন স্ট্যান্ডার্ড ছাড়, PF, পেশাগত কর, ক্রেডিট, cess বা surcharge বাদ দেয় না।", "বার্ষিক মোট=মাসিক×12। মডেল কর=স্ল্যাব ও সরলীকৃত ছাড়; মডেল নিট=মোট−কর−প্রদত্ত অবদান।", "বার্ষিক ₹1,500,000 মোট বেতন ও আলাদা অবদান 0% হলে মডেল কর ₹105,000, আনুমানিক নিট ₹1,395,000/বছর (₹116,250/মাস)। ছাড়ের আগে মোট বেতন করের ভিত্তি।", "এটি কি ভারতে আমার প্রকৃত হাতে-পাওয়া বেতন?", "না। FY 2025–26 নতুন ব্যবস্থায় ₹75,000 বেতন ছাড় থাকতে পারে, কিন্তু ইঞ্জিন তা বাদ দেয় না। PF, রাজ্য পেশাগত কর, TDS সমন্বয়, cess, surcharge ও ব্যক্তিগত ছাড়ও অনুপস্থিত; আইনি নির্ভুলতা যাচাই বাকি।"],
  },
  uk: {
    gst: ["Введіть суму до податку або загальну, виберіть напрям і ставку GST для товару/послуги. Окремо перевірте класифікацію HSN/SAC та постачання в межах штату чи між штатами.", "GST на базу=база×введена ставка/100; загальна=база+GST. Для суми з податком база=загальна/(1+введена ставка/100).", "₹10 000 без податку за введених 18% дають ₹1 800 GST і ₹11 800 разом. 18% — лише приклад, не єдина ставка для товарів.", "Чи кожен товар в Індії оподатковується GST 18%?", "Ні. Ставка залежить від класифікації HSN/SAC і постачання. Інструмент не класифікує товар і не розділяє CGST/SGST та IGST."],
    tax: ["Введіть звичайний оподатковуваний дохід для сценарію нового режиму AY 2026–27. Інструмент не визначає резидентство, категорію доходу або право на інші відрахування.", "Прогресивний податок=0% до ₹400 000 + 5% до ₹800 000 + 10% до ₹1 200 000 + 15% до ₹1 600 000 + 20% до ₹2 000 000 + 25% до ₹2 400 000 + 30% понад. Движок спрощено застосовує пільгу/граничне полегшення Section 87A.", "За оподатковуваного доходу ₹1 500 000 модельний податок за діапазонами ₹105 000, у середньому 7%. Приклад до спеціального доходу, cess і надбавки.", "Чи завжди дохід до ₹1 200 000 не оподатковується?", "Пільга 87A нового режиму AY 2026–27 доступна лише резидентам, які відповідають вимогам, і не компенсує податок зі спеціального доходу. Інструмент не запитує резидентство чи тип доходу, тому це не остаточний податок."],
    salary: ["Введіть річну або місячну зарплату брутто та окреме припущення внесків. Модель використовує нові ставки, але не віднімає зарплатний стандартний відрахунок ₹75 000, PF, професійний податок, кредити, cess або надбавку.", "Річне брутто=місячне×12. Модельний податок=діапазони та спрощена пільга; модельне нетто=брутто−податок−введений внесок.", "За річного брутто ₹1 500 000 і окремого внеску 0% модельний податок ₹105 000, нетто ₹1 395 000/рік (₹116 250/міс.). Брутто є базою до зарплатних відрахувань.", "Це моя фактична зарплата на руки в Індії?", "Ні. У FY 2025–26 новий режим може дозволяти зарплатне відрахування ₹75 000, яке движок пропускає. Також немає PF, професійного податку штату, звірки TDS, cess, надбавки й особистих відрахувань; правова точність ще не підтверджена."],
  },
  ms: {
    gst: ["Masukkan amaun sebelum cukai atau jumlah, pilih arah dan kadar GST bagi barang/perkhidmatan. Semak klasifikasi HSN/SAC dan bekalan dalam negeri atau antara negeri secara berasingan.", "GST atas asas=asas×kadar dimasukkan/100; jumlah=asas+GST. Untuk jumlah termasuk cukai, asas=jumlah/(1+kadar dimasukkan/100).", "Asas ₹10,000 pada 18% yang dimasukkan menghasilkan GST ₹1,800 dan jumlah ₹11,800. 18% ialah input contoh, bukan kadar semua produk.", "Adakah semua produk India dikenakan GST 18%?", "Tidak. Kadar bergantung pada klasifikasi HSN/SAC dan jenis bekalan. Alat tidak mengelaskan barang atau memisahkan CGST/SGST daripada IGST."],
    tax: ["Masukkan pendapatan bercukai biasa bagi senario rejim baharu AY 2026–27. Alat tidak menentukan pemastautin, kategori pendapatan atau kelayakan potongan lain.", "Cukai progresif=0% hingga ₹400,000 + 5% hingga ₹800,000 + 10% hingga ₹1,200,000 + 15% hingga ₹1,600,000 + 20% hingga ₹2,000,000 + 25% hingga ₹2,400,000 + 30% lebihan. Enjin turut mempermudah rebat/relief marginal Seksyen 87A.", "Pada pendapatan bercukai ₹1,500,000, cukai model mengikut jalur ialah ₹105,000, purata 7%. Contoh sebelum pendapatan kadar khas, cess dan surcharge.", "Adakah cukai sentiasa sifar sehingga ₹1,200,000?", "Rebat 87A rejim baharu AY 2026–27 hanya untuk individu pemastautin yang layak dan tidak mengimbangi cukai pendapatan berkadar khas. Alat tidak meminta pemastautin atau jenis pendapatan; hasil bukan liabiliti akhir."],
    salary: ["Masukkan gaji kasar tahunan atau bulanan dan andaian caruman berasingan. Model menggunakan jalur rejim baharu tetapi tidak menolak potongan gaji standard ₹75,000, PF, cukai profesional, kredit, cess atau surcharge.", "Gaji tahunan=gaji bulanan×12. Cukai model=jalur dan rebat ringkas; bersih model=kasar−cukai−caruman yang dimasukkan.", "Dengan gaji kasar ₹1,500,000 setahun dan caruman berasingan 0%, cukai model ₹105,000 dan bersih anggaran ₹1,395,000/tahun (₹116,250/bulan). Gaji kasar menjadi asas sebelum potongan.", "Adakah ini gaji bersih sebenar saya di India?", "Tidak. Dalam FY 2025–26, rejim baharu boleh membenarkan potongan gaji ₹75,000 tetapi enjin tidak menggunakannya. PF, cukai profesional negeri, pelarasan TDS, cess, surcharge dan potongan peribadi juga tidak termasuk; ketepatan undang-undang belum selesai."],
  },
  sv: {
    gst: ["Ange belopp före skatt eller totalsumma, välj riktning och ange GST-satsen för varan/tjänsten. Kontrollera HSN/SAC-klassificering och leverans inom eller mellan delstater separat.", "GST på underlag=underlag×angiven sats/100; totalt=underlag+GST. För summa inklusive skatt=totalt/(1+angiven sats/100).", "₹10 000 före skatt med angivna 18% ger ₹1 800 GST och ₹11 800 totalt. 18% är exemplet, inte en gemensam sats för alla varor.", "Gäller 18% GST för varje indisk produkt?", "Nej. Satsen beror på HSN/SAC-klassificering och leveranstyp. Verktyget klassificerar inte varan eller delar upp CGST/SGST och IGST."],
    tax: ["Ange vanlig beskattningsbar inkomst för det nya systemet AY 2026–27. Verktyget avgör inte hemvist, inkomstslag eller rätt till andra avdrag.", "Progressiv skatt=0% till ₹400 000 + 5% till ₹800 000 + 10% till ₹1 200 000 + 15% till ₹1 600 000 + 20% till ₹2 000 000 + 25% till ₹2 400 000 + 30% över. Motorn tillämpar Section 87A-avdrag och marginal lättnad förenklat.", "Vid ₹1 500 000 beskattningsbar inkomst är modellskatten ₹105 000, i genomsnitt 7%. Exempel före särskilt beskattad inkomst, cess och tillägg.", "Är skatten alltid noll vid inkomst upp till ₹1 200 000?", "Section 87A-avdraget i nya systemet AY 2026–27 gäller endast behöriga bosatta individer och kvittar inte skatt på specialinkomst. Verktyget frågar inte om hemvist eller inkomstslag, så detta är inget slutligt skattebelopp."],
    salary: ["Ange års- eller månadslön brutto och ett separat antagande om avgifter. Modellen använder nya skikt men drar inte av standardavdraget ₹75 000, PF, yrkesskatt, krediter, cess eller tillägg.", "Annualiserad lön=månad×12. Modellerad skatt=skikt och förenklat avdrag; modellerat netto=brutto−skatt−angiven avgift.", "Vid ₹1 500 000 i årslön och separat avgift 0% är modellskatten ₹105 000 och nettot ₹1 395 000/år (₹116 250/mån). Brutto används som underlag före löneavdrag.", "Är detta min verkliga nettolön i Indien?", "Nej. Under FY 2025–26 kan det nya systemet medge ₹75 000 standardavdrag för lön, men motorn utelämnar det. PF, delstatlig yrkesskatt, TDS-avstämning, cess, tillägg och personliga avdrag saknas också; juridisk noggrannhet är inte färdiggranskad."],
  },
  cs: {
    gst: ["Zadejte částku bez daně nebo celkovou, zvolte směr a sazbu GST pro zboží/službu. Samostatně ověřte klasifikaci HSN/SAC a dodání v rámci státu či mezi státy.", "GST ze základu=základ×zadaná sazba/100; celkem=základ+GST. U částky včetně daně základ=celkem/(1+zadaná sazba/100).", "Základ ₹10 000 při zadaných 18% dává GST ₹1 800 a celkem ₹11 800. 18% je vstup příkladu, nikoli jednotná sazba pro vše.", "Platí GST 18% na každý indický výrobek?", "Ne. Sazba závisí na klasifikaci HSN/SAC a dodání. Nástroj zboží nezařazuje ani nerozděluje CGST/SGST a IGST."],
    tax: ["Zadejte běžný zdanitelný příjem pro scénář nového režimu AY 2026–27. Nástroj neurčuje rezidenci, druh příjmu ani nárok na další odpočty.", "Progresivní daň=0% do ₹400 000 + 5% do ₹800 000 + 10% do ₹1 200 000 + 15% do ₹1 600 000 + 20% do ₹2 000 000 + 25% do ₹2 400 000 + 30% nad limit. Motor zjednodušeně uplatňuje Section 87A rebate/marginal relief.", "Při zdanitelném příjmu ₹1 500 000 činí modelová daň podle pásem ₹105 000, průměrně 7%. Příklad před zvláštním příjmem, cess a přirážkou.", "Je příjem do ₹1 200 000 vždy bez daně?", "Rebate 87A nového režimu AY 2026–27 náleží pouze způsobilým rezidentům a nesnižuje daň ze zvláštního příjmu. Nástroj se neptá na rezidenci ani druh příjmu, takže nejde o konečnou daň."],
    salary: ["Zadejte roční nebo měsíční hrubou mzdu a samostatný předpoklad příspěvků. Model použije pásma nového režimu, ale neodečte standardní mzdový odpočet ₹75 000, PF, profesní daň, kredity, cess ani přirážku.", "Roční hrubá mzda=měsíční×12. Modelová daň=pásma a zjednodušená sleva; modelové netto=hrubá−daň−zadaný příspěvek.", "Při roční hrubé mzdě ₹1 500 000 a odděleném příspěvku 0% činí modelová daň ₹105 000 a čistá mzda ₹1 395 000/rok (₹116 250/měsíc). Hrubá mzda je základem před srážkami.", "Je to moje skutečná čistá mzda v Indii?", "Ne. Nový režim FY 2025–26 může umožnit mzdový odpočet ₹75 000, který motor vynechává. Chybí také PF, státní profesní daň, vyrovnání TDS, cess, přirážka a osobní odpočty; právní přesnost není dokončena."],
  },
  ro: {
    gst: ["Introdu suma fără taxă sau totalul, alege direcția și indică rata GST a produsului/serviciului. Verifică separat clasificarea HSN/SAC și dacă livrarea este în stat sau între state.", "GST la bază=bază×rata introdusă/100; total=bază+GST. Pentru total cu taxă inclusă, bază=total/(1+rata introdusă/100).", "Baza ₹10.000 la 18% introdus generează GST ₹1.800 și total ₹11.800. 18% este valoarea exemplului, nu o rată universală.", "Toate produsele indiene au GST 18%?", "Nu. Rata depinde de clasificarea HSN/SAC și de livrare. Instrumentul nu clasifică bunul și nu separă CGST/SGST de IGST."],
    tax: ["Introdu venitul obișnuit impozabil pentru scenariul noului regim AY 2026–27. Instrumentul nu determină rezidența, categoria venitului sau dreptul la alte deduceri.", "Impozit progresiv=0% până la ₹400.000 + 5% până la ₹800.000 + 10% până la ₹1.200.000 + 15% până la ₹1.600.000 + 20% până la ₹2.000.000 + 25% până la ₹2.400.000 + 30% peste. Motorul aplică simplificat rebate/relief marginal Section 87A.", "La venit impozabil ₹1.500.000, impozitul modelat pe tranșe este ₹105.000, media 7%. Exemplu înainte de venituri cu rată specială, cess și suprataxă.", "Venitul până la ₹1.200.000 este întotdeauna fără impozit?", "Rebate 87A al noului regim AY 2026–27 este doar pentru rezidenți eligibili și nu compensează impozitul pe venit special. Instrumentul nu cere rezidența sau categoria venitului, deci nu oferă obligația finală."],
    salary: ["Introdu salariul brut anual sau lunar și o ipoteză separată pentru contribuții. Modelul folosește tranșele noi, dar nu scade deducerea salarială standard ₹75.000, PF, taxa profesională, credite, cess sau suprataxă.", "Brut anualizat=lunar×12. Impozit modelat=tranșe și rebate simplificat; net modelat=brut−impozit−contribuția introdusă.", "La brut anual ₹1.500.000 și contribuție separată 0%, impozitul modelat este ₹105.000 și netul estimat ₹1.395.000/an (€116.250/lună). Brutul este baza înaintea deducerilor salariale.", "Este acesta salariul meu net real în India?", "Nu. FY 2025–26 poate permite o deducere salarială de ₹75.000 în noul regim, omisă de motor. PF, taxa profesională de stat, reconcilierea TDS, cess, suprataxa și deducerile personale lipsesc; precizia juridică nu a fost încheiată."],
  },
  el: {
    gst: ["Εισαγάγετε καθαρό ποσό ή σύνολο, επιλέξτε κατεύθυνση και συντελεστή GST για το αγαθό/υπηρεσία. Ελέγξτε χωριστά την ταξινόμηση HSN/SAC και αν η παροχή είναι εντός ή μεταξύ πολιτειών.", "GST στη βάση=βάση×εισαγόμενος συντελεστής/100· σύνολο=βάση+GST. Για ποσό με φόρο, βάση=σύνολο/(1+εισαγόμενος συντελεστής/100).", "Καθαρή βάση ₹10.000 με εισαγόμενο 18% δίνει GST ₹1.800 και σύνολο ₹11.800. Το 18% είναι τιμή παραδείγματος, όχι ενιαίος συντελεστής.", "Όλα τα προϊόντα στην Ινδία έχουν GST 18%;", "Όχι. Ο συντελεστής εξαρτάται από την ταξινόμηση HSN/SAC και την παροχή. Το εργαλείο δεν ταξινομεί το αγαθό ούτε διαχωρίζει CGST/SGST και IGST."],
    tax: ["Εισαγάγετε συνηθισμένο φορολογητέο εισόδημα για το νέο καθεστώς AY 2026–27. Το εργαλείο δεν προσδιορίζει κατοικία, κατηγορία εισοδήματος ή δικαίωμα άλλων εκπτώσεων.", "Προοδευτικός φόρος=0% έως ₹400.000 + 5% έως ₹800.000 + 10% έως ₹1.200.000 + 15% έως ₹1.600.000 + 20% έως ₹2.000.000 + 25% έως ₹2.400.000 + 30% πάνω από αυτό. Ο μηχανισμός απλοποιεί την έκπτωση/οριακή ελάφρυνση Section 87A.", "Με φορολογητέο εισόδημα ₹1.500.000, ο μοντελοποιημένος φόρος είναι ₹105.000, μέσος 7%. Παράδειγμα πριν από ειδικό εισόδημα, cess και προσαύξηση.", "Είναι πάντα μηδενικός ο φόρος έως ₹1.200.000;", "Η έκπτωση 87A του νέου καθεστώτος AY 2026–27 αφορά μόνο επιλέξιμους κατοίκους και δεν συμψηφίζει φόρο ειδικού εισοδήματος. Δεν ζητείται κατοικία ή τύπος εισοδήματος, επομένως δεν είναι τελική οφειλή."],
    salary: ["Εισαγάγετε ετήσιο ή μηνιαίο μικτό μισθό και χωριστή υπόθεση εισφορών. Το μοντέλο χρησιμοποιεί τις κλίμακες νέου καθεστώτος, αλλά δεν αφαιρεί την τυπική έκπτωση μισθού ₹75.000, PF, επαγγελματικό φόρο, πιστώσεις, cess ή προσαύξηση.", "Ετησιοποιημένο μικτό=μηνιαίο×12. Μοντελοποιημένος φόρος=κλίμακες και απλοποιημένη έκπτωση· καθαρό=μικτό−φόρος−εισαγόμενη εισφορά.", "Με ετήσιο μικτό ₹1.500.000 και ξεχωριστή εισφορά 0%, ο φόρος μοντέλου είναι ₹105.000 και το εκτιμώμενο καθαρό ₹1.395.000/έτος (₹116.250/μήνα). Το μικτό χρησιμοποιείται πριν από κρατήσεις.", "Είναι αυτός ο πραγματικός καθαρός μισθός μου στην Ινδία;", "Όχι. Το FY 2025–26 το νέο καθεστώς μπορεί να επιτρέπει έκπτωση μισθού ₹75.000 που ο κινητήρας παραλείπει. PF, κρατικός επαγγελματικός φόρος, συμφωνία TDS, cess, προσαύξηση και προσωπικές εκπτώσεις επίσης λείπουν· η νομική ακρίβεια δεν έχει επιβεβαιωθεί."],
  },
};

export const indiaPolicyFollowups: Record<SupportedLocale, LocaleFollowup> = Object.fromEntries(
  Object.entries(copy).map(([locale, text]) => [locale, {
    "india-gst-calculator": { howTo: text.gst[0], formula: text.gst[1], exampleNote: text.gst[2], faq: { question: text.gst[3], answer: text.gst[4] } },
    "india-income-tax-calculator": { howTo: text.tax[0], formula: text.tax[1], exampleNote: text.tax[2], faq: { question: text.tax[3], answer: text.tax[4] } },
    "india-gross-net-salary-calculator": { howTo: text.salary[0], formula: text.salary[1], exampleNote: text.salary[2], faq: { question: text.salary[3], answer: text.salary[4] } },
  }]),
) as unknown as Record<SupportedLocale, LocaleFollowup>;
